const futures = $json?.data?.items ?? [];

if (!Array.isArray(futures) || futures.length === 0) {
  throw new Error('Tastytrade returned no listed CL futures contracts');
}

const contracts = futures
  .filter(contract => contract.symbol?.startsWith('/CL'))
  .sort((a, b) => String(a['expiration-date']).localeCompare(String(b['expiration-date'])))
  .map(contract => ({
    symbol: contract.symbol,
    expiration_date: contract['expiration-date'] ?? '',
    active_month: contract['active-month'] === true,
    next_active_month: contract['next-active-month'] === true,
    is_tradeable: contract['is-tradeable'] !== false,
    is_closing_only: contract['is-closing-only'] === true
  }));

if (contracts.length === 0) {
  throw new Error('No /CL contracts remained after filtering');
}

const BATCH_SIZE = 90;
const batches = [];

for (let index = 0; index < contracts.length; index += BATCH_SIZE) {
  const batchContracts = contracts.slice(index, index + BATCH_SIZE);
  batches.push({
    json: {
      batch_number: Math.floor(index / BATCH_SIZE) + 1,
      total_contracts: contracts.length,
      symbols_csv: batchContracts.map(contract => contract.symbol).join(','),
      contracts: batchContracts
    }
  });
}

return batches;

const responses = $input.all();
const batches = $('Prepare CL Contract Batches1').all();

const marketBySymbol = new Map();
const contractBySymbol = new Map();

for (const batch of batches) {
  for (const contract of batch.json.contracts ?? []) {
    contractBySymbol.set(contract.symbol, contract);
  }
}

for (const response of responses) {
  const marketItems = response.json?.data?.items ?? [];
  for (const market of marketItems) {
    if (market?.symbol) marketBySymbol.set(market.symbol, market);
  }
}

const summaryDates = [...marketBySymbol.values()]
  .map(market => market['summary-date'])
  .filter(Boolean)
  .sort();

const fallbackTradeDate = summaryDates.at(-1) ?? new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/New_York',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).format(new Date());

const numberOrBlank = value => {
  if (value === null || value === undefined || value === '') return '';
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : '';
};

const rows = [];

for (const contract of [...contractBySymbol.values()].sort((a, b) =>
  String(a.expiration_date).localeCompare(String(b.expiration_date))
)) {
  const market = marketBySymbol.get(contract.symbol);
  const high = market?.['day-high-price'] ?? market?.['day-high'];
  const low = market?.['day-low-price'] ?? market?.['day-low'];
  const tradeDate = market?.['summary-date'] ?? fallbackTradeDate;

  let dataStatus = 'OK';
  if (!market) dataStatus = 'NO_MARKET_DATA';
  else if (high === null || high === undefined || low === null || low === undefined) dataStatus = 'NO_TRADES';

  rows.push({
    json: {
      unique_key: `${tradeDate}|${contract.symbol}`,
      trade_date: tradeDate,
      root_symbol: '/CL',
      contract_symbol: contract.symbol,
      expiration_date: contract.expiration_date,
      active_month: contract.active_month ? 'YES' : 'NO',
      next_active_month: contract.next_active_month ? 'YES' : 'NO',
      data_status: dataStatus,
      day_high: numberOrBlank(high),
      day_low: numberOrBlank(low),
      open: numberOrBlank(market?.open ?? market?.['day-open']),
      close: numberOrBlank(market?.close ?? market?.['day-close']),
      last: numberOrBlank(market?.last),
      bid: numberOrBlank(market?.bid),
      ask: numberOrBlank(market?.ask),
      mark: numberOrBlank(market?.mark),
      volume: numberOrBlank(market?.volume),
      source_updated_at: market?.['updated-at'] ?? '',
      fetched_at_utc: new Date().toISOString()
    }
  });
}

if (rows.length === 0) {
  throw new Error('No CL contract rows were produced');
}

return rows;

const output = [];
const seen = new Set();

const isValidNumber = (value) => {
  if (value === null || value === undefined || value === '') return false;
  return Number.isFinite(Number(value));
};

for (const item of $input.all()) {
  const rows = item.json.rows;

  if (!Array.isArray(rows)) {
    throw new Error('Extracted historical data is not an array');
  }

  for (const row of rows) {
    const hasCompleteOHLC = [
      row.open,
      row.day_high,
      row.day_low,
      row.close
    ].every(isValidNumber);

    if (!hasCompleteOHLC) continue;
    if (!row.unique_key || seen.has(row.unique_key)) continue;

    seen.add(row.unique_key);
    output.push({ json: row });
  }
}

return output;

const futures = $json?.data?.items ?? [];

if (!Array.isArray(futures) || futures.length === 0) {
  throw new Error('No listed CL contracts returned');
}

const BATCH_SIZE = 10;
const fromTime = 1_000_000_000;

const contracts = futures
  .filter(contract =>
    contract.symbol?.startsWith('/CL') &&
    contract['streamer-symbol'] &&
    contract['is-tradeable'] !== false
  )
  .sort((a, b) =>
    String(a['expiration-date'] ?? '')
      .localeCompare(String(b['expiration-date'] ?? ''))
  )
  .map(contract => ({
    contract_symbol: contract.symbol,
    streamer_symbol: contract['streamer-symbol'],
    expiration_date: contract['expiration-date'] ?? '',
    active_month: contract['active-month'] === true ? 'YES' : 'NO',
    next_active_month: contract['next-active-month'] === true ? 'YES' : 'NO'
  }));

if (contracts.length === 0) {
  throw new Error('No CL contracts with streamer symbols were found');
}

const totalBatches = Math.ceil(contracts.length / BATCH_SIZE);
const output = [];

for (let index = 0; index < contracts.length; index += BATCH_SIZE) {
  const batchContracts = contracts.slice(index, index + BATCH_SIZE);
  const batchNumber = Math.floor(index / BATCH_SIZE) + 1;

  const request = {
    batch_number: batchNumber,
    from_time: fromTime,
    history_mode: 'MAX_AVAILABLE',
    contracts: batchContracts
  };

  output.push({
    json: {
      batch_number: batchNumber,
      total_batches: totalBatches,
      total_contracts: contracts.length,
      contracts_in_batch: batchContracts.length,
      history_mode: 'MAX_AVAILABLE',
      from_time: fromTime,
      batch_base64: Buffer
        .from(JSON.stringify(request), 'utf8')
        .toString('base64url')
    }
  });
}

return output;

const futures = $json?.data?.items ?? [];

if (!Array.isArray(futures) || futures.length === 0) {
  throw new Error('No listed CL contracts returned');
}

const DAYS_BACK = 7;
const DAY_MS = 24 * 60 * 60 * 1000;
const BATCH_SIZE = 10;
const now = new Date();

// Use UTC midnight boundaries so this fetches seven complete candle dates.
// Example: when run on Sep 1 UTC, the range is Aug 25 through Aug 31.
const toTime = Date.UTC(
  now.getUTCFullYear(),
  now.getUTCMonth(),
  now.getUTCDate()
);
const fromTime = toTime - DAYS_BACK * DAY_MS;

const contracts = futures
  .filter(contract =>
    contract.symbol?.startsWith('/CL') &&
    contract['streamer-symbol'] &&
    contract['is-tradeable'] !== false
  )
  .sort((a, b) =>
    String(a['expiration-date'] ?? '')
      .localeCompare(String(b['expiration-date'] ?? ''))
  )
  .map(contract => ({
    contract_symbol: contract.symbol,
    streamer_symbol: contract['streamer-symbol'],
    expiration_date: contract['expiration-date'] ?? '',
    active_month: contract['active-month'] === true ? 'YES' : 'NO',
    next_active_month: contract['next-active-month'] === true ? 'YES' : 'NO'
  }));

if (contracts.length === 0) {
  throw new Error('No CL contracts with streamer symbols were found');
}

const totalBatches = Math.ceil(contracts.length / BATCH_SIZE);
const output = [];

for (let index = 0; index < contracts.length; index += BATCH_SIZE) {
  const batchContracts = contracts.slice(index, index + BATCH_SIZE);
  const batchNumber = Math.floor(index / BATCH_SIZE) + 1;

  const request = {
    batch_number: batchNumber,
    from_time: fromTime,
    to_time: toTime,
    days_back: DAYS_BACK,
    history_mode: 'LAST_7_COMPLETED_UTC_DAYS',
    contracts: batchContracts
  };

  output.push({
    json: {
      batch_number: batchNumber,
      total_batches: totalBatches,
      total_contracts: contracts.length,
      contracts_in_batch: batchContracts.length,
      from_time: fromTime,
      to_time: toTime,
      start_date_utc: new Date(fromTime).toISOString().slice(0, 10),
      end_date_utc: new Date(toTime - DAY_MS).toISOString().slice(0, 10),
      batch_base64: Buffer
        .from(JSON.stringify(request), 'utf8')
        .toString('base64url')
    }
  });
}

return output;

const output = [];
const seen = new Set();

const isValidNumber = (value) => {
  if (value === null || value === undefined || value === '') return false;
  return Number.isFinite(Number(value));
};

for (const item of $input.all()) {
  const rows = item.json.rows;

  if (!Array.isArray(rows)) {
    throw new Error('Extracted last-week data is not an array');
  }

  for (const row of rows) {
    const hasCompleteOHLC = [
